"""Opening book generated by the referee: short random openings with equal material.

Each opening is played twice with colours swapped, so an unbalanced one cancels out inside
its pair. Replaced by a Stockfish-filtered book in M6.
"""

import random

import chess

VALUES = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}


def _material(board: chess.Board, color: chess.Color) -> int:
    return sum(len(board.pieces(piece, color)) * value for piece, value in VALUES.items())


def generate(rng: random.Random, count: int, plies: int = 8) -> list[str]:
    """`count` distinct EPD lines (FEN without the move counters)."""
    book: dict[str, None] = {}
    attempts = 0
    while len(book) < count:
        attempts += 1
        if attempts > count * 50:
            raise ValueError(f"could not generate {count} distinct openings")
        board = chess.Board()
        for _ in range(plies):
            board.push(rng.choice(list(board.legal_moves)))
        balanced = _material(board, chess.WHITE) == _material(board, chess.BLACK)
        if balanced and not board.is_check() and not board.is_game_over():
            book[board.epd()] = None
    return list(book)
